def main(args=sys.argv):
    parser = option_parser()
    if len(args) < 2:
        parser.print_help()
        return 1
    if args[1] not in COMMANDS:
        if args[1] == '--version':
            parser.print_version()
            return 0
        parser.print_help()
        return 1

    command = eval('command_' + args[1])
    dbpath = prefs['library_path']

    return command(args[2:], dbpath)


if __name__ == '__main__':
    sys.exit(main())

