def send_message(msg=''):
    global do_notify
    if not do_notify:
        return
    prints('Notifying calibre of the change')
    from calibre.utils.ipc import RC
    t = RC(print_error=False)
    t.start()
    t.join(3)
    if t.done:
        t.conn.send('refreshdb:'+msg)
        t.conn.close()


def write_dirtied(db):
    prints('Backing up metadata')
    db.dump_metadata()


def get_parser(usage):
    parser = OptionParser(usage)
    go = parser.add_option_group(_('GLOBAL OPTIONS'))
    go.is_global_options = True
    go.add_option('--library-path', '--with-library', default=None, help=_('Path to the calibre library. Default is to use the path stored in the settings.'))
    go.add_option('--dont-notify-gui', default=False, action='store_true',
            help=_('Do not notify the running calibre GUI (if any) that the database has'
                ' changed. Use with care, as it can lead to database corruption!'))
    go.add_option('-h', '--help', help=_('show this help message and exit'), action='help')
    go.add_option('--version', help=_("show program's version number and exit"), action='version')

    return parser


def get_db(dbpath, options):
    global do_notify
    if options.library_path is not None:
        dbpath = os.path.expanduser(options.library_path)
    if dbpath is None:
        raise ValueError('No saved library path, either run the GUI or use the'
                ' --with-library option')
    dbpath = os.path.abspath(dbpath)
    if options.dont_notify_gui:
        do_notify = False
    return LibraryDatabase(dbpath)


def _field_name(db, f):
    """Return the display name for a field, handling custom columns."""
    ans = f
    if f[0] == '*':
        if f.endswith('_index'):
            fkey = f[1:-len('_index')]
            num = db.custom_column_label_map[fkey]['num']
            ans = '%d_index' % num
        else:
            ans = db.custom_column_label_map[f[1:]]['num']
    return ans


def _prepare_record_formats(record):
    """Format the formats list for display."""
    fmts = [x for x in record['formats'] if x is not None]
    record['formats'] = u'[%s]' % u', '.join(fmts)


def _convert_record_fields(record):
    """Convert record fields to strings and handle isoformat."""
    for f in record.keys():
        val = record[f]
        if hasattr(val, 'isoformat'):
            record[f] = isoformat(val, as_utc=False)
        else:
            record[f] = unicode(val)
        record[f] = record[f].replace('\n', ' ')


def _compute_widths(data, fields, separator):
    """Compute column widths for table output."""
    widths = [0] * len(fields)

    def chr_width(x):
        return 1 + unicodedata.east_asian_width(x).startswith('W')

    def str_width(x):
        return sum(map(chr_width, x))

    for record in data:
        for j, field in enumerate(fields):
            widths[j] = max(widths[j], str_width(record[field]))

    return widths


def _adjust_widths(widths, screen_width):
    """Adjust column widths to fit within screen width."""
    field_width = screen_width // len(widths)
    base_widths = [min(x + 1, field_width) for x in widths]

    while sum(base_widths) < screen_width:
        adjusted = False
        for i in range(len(widths)):
            if base_widths[i] < widths[i]:
                base_widths[i] += min(screen_width - sum(base_widths), widths[i] - base_widths[i])
                adjusted = True
                break
        if not adjusted:
            break
    return base_widths


def _print_table(data, fields, widths, separator):
    """Print the table of records."""
    from calibre.utils.terminal import geometry, ColoredStream

    titles = [('%-*s%s' % (w - len(separator), f, separator)) for w, f in zip(widths, fields)]
    with ColoredStream(sys.stdout, fg='green'):
        print ''.join(titles)

    wrappers = [TextWrapper(w - 1).wrap if w > 1 else lambda y: y for w in widths]
    o = cStringIO.StringIO()

    for record in data:
        text = [wrappers[i](unicode(record[field])) for i, field in enumerate(fields)]
        lines = max(map(len, text))
        for l in range(lines):
            for i, field in enumerate(text):
                ft = field[l] if l < len(field) else u''
                o.write(ft.encode('utf-8'))
                if i < len(text) - 1:
                    filler = (u'%*s' % (widths[i] - len(ft) - 1, u''))
                    o.write((filler + separator).encode('utf-8'))
            print >>o
    return o.getvalue()


def do_list(db, fields, afields, sort_by, ascending, search_text, line_width, separator,
            prefix, limit, for_machine=False):
    from calibre.utils.terminal import ColoredStream, geometry
    if sort_by is None:
        ascending = True
    db.sort(sort_by or 'id', ascending)
    if search_text:
        db.search(search_text)
    data = db.get_data_as_dict(prefix, authors_as_string=True, convert_to_local_tz=False)
    if limit > -1:
        data = data[:limit]
    try:
        fields.remove('id')
    except ValueError:
        pass
    fields = ['id'] + fields
    title_fields = fields

    if for_machine:
        import json
        record_keys = {_field_name(db, field): field for field in fields}
        for record in data:
            for key in set(record) - set(record_keys):
                del record[key]
            for key in tuple(record):
                if record_keys[key] != key:
                    record[record_keys[key]] = record.pop(key)
            for key, val in tuple(record.iteritems()):
                if hasattr(val, 'isoformat'):
                    record[key] = isoformat(val, as_utc=True)
                elif val is None:
                    del record[key]
                elif key == 'languages' and val:
                    record[key] = val.split(',')
        return json.dumps(data, indent=2, sort_keys=True)

    # Normal table output
    for record in data:
        _prepare_record_formats(record)
    for record in data:
        _convert_record_fields(record)

    widths = _compute_widths(data, fields, separator)
    screen_width = geometry()[0] if line_width < 0 else line_width
    if not screen_width:
        screen_width = 80
    widths = _adjust_widths(widths, screen_width)

    return _print_table(data, fields, widths, separator)


