                self.new_api.set_field('cover', {book_id:bool(val)})
        else:
            null_field = field in {'title', 'sort', 'uuid'}
            retval = (True if field == 'sort' else None)

            def func(self, book_id, val, notify=True, commit=True):
                if not val and null_field:
